from collections import Counter

def transform(grid):
    """
    ARC task: 2-line (full row/col of 2s) is directional indicator.
    Find content (non-background), place 8s parallel at far edge opposite 2-line.
    """
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find background (most common)
    bg = max(set(r[c] for r in grid for c in range(w)), 
             key=lambda x: sum(1 for r in grid for c in range(w) if r[c] == x))

    # Find 2-line
    for i in range(h):
        if all(grid[i][j] == 2 for j in range(w)):
            two_row, two_type = i, 0
            break
    else:
        for j in range(w):
            if all(grid[i][j] == 2 for i in range(h)):
                two_col, two_type = j, 1
                break

    # Find 8-line position
    if two_type == 0:  # Horizontal at row r
        target_rows = [i for i in range(h) if i != two_row]
        content_rows = [i for i in target_rows if any(grid[i][c] != bg and grid[i][c] != 2 for c in range(w))]

        if content_rows:
            below = [i for i in content_rows if i > two_row]
            above = [i for i in content_rows if i < two_row]
        else:
            below = []
            above = []

        if below:
            target_row = max(below) + 1 if max(below) + 1 < h else max(below)
        elif above:
            target_row = min(above) - 1 if min(above) - 1 >= 0 else min(above)
        else:
            target_row = two_row

        for c in range(w):
            if grid[target_row][c] != bg and grid[target_row][c] != 2:
                result[target_row][c] = 8

    else:  # Vertical
        target_cols = [j for j in range(w) if j != two_col]
        content_cols = [j for j in target_cols if any(grid[i][j] != bg and grid[i][j] != 2 for i in range(h))]

        if content_cols:
            right = [j for j in content_cols if j > two_col]
            left = [j for j in content_cols if j < two_col]
        else:
            right = []
            left = []

        if right:
            target_col = max(right) + 1 if max(right) + 1 < w else max(right)
        elif left:
            target_col = min(left) - 1 if min(left) - 1 >= 0 else min(left)
        else:
            target_col = two_col

        for r in range(h):
            if grid[r][target_col] != bg and grid[r][target_col] != 2:
                grid[r][target_col] = 8

    return result
'''

